<!doctype html><html lang="fa" dir="rtl"><meta charset="utf-8"><title>پرسنل</title><style>body{font-family:Tahoma;background:#07111f;color:#e9f3fb;padding:30px}.panel{background:#0a1b2b;border:1px solid #1b354b;border-radius:16px;padding:20px;max-width:800px;margin:auto}label{display:block;margin:12px 0 5px}input{width:100%;padding:10px;background:#081522;border:1px solid #29465e;color:white;border-radius:8px}button{margin-top:18px;padding:10px 20px;background:#123b4d;color:#6ee7d0;border:0;border-radius:8px}</style><div class="panel"><h1>{{ $personnel->exists ? 'ویرایش پرسنل' : 'ایجاد پرسنل' }}</h1><p>ایجاد شخص جدید از بخش کاربران انجام می‌شود تا User و Personnel همیشه یکدیگر را داشته باشند.</p><form method="POST" action="{{ $personnel->exists ? route('personnel.update',$personnel) : route('personnel.store') }}">@csrf @if($personnel->exists) @method('PUT') @endif @foreach(['code'=>'کد پرسنلی','first_name'=>'نام','last_name'=>'نام خانوادگی','national_id'=>'کد ملی','job_title'=>'عنوان شغلی','phone'=>'تلفن','mobile'=>'موبایل','email'=>'ایمیل'] as $field=>$label)<label>{{ $label }}</label><input name="{{ $field }}" value="{{ old($field,$personnel->$field) }}">@endforeach<button>ذخیره</button></form></div></html>